 q:[["Heute ___ ich Tee. (ууна)",["trinke","ich","trinken"],0],["___ du Tee? (уудаг уу)",["Trinkst","Trinke","Trinken"],0],["Ich ___ Wasser. (уудаг)",["trinke","trinkst","trinkt"],0]],
