 ex:[["She speaks slowly.","Тэр удаан ярьдаг."],["He drives carefully.","Тэр болгоомжтой жолоодно."],["She sings well.","Тэр сайхан дуулдаг."],["He runs fast.","Тэр хурдан гүйнэ."]],
