 rule:"читай! / читайте! · пиши! / пишите! · не + V",
 ex:[["Читай книгу!","Ном унш!"],["Пишите, пожалуйста.","Бичнэ үү."],["Не говори так!","Тэгж битгий хэл!"],["Иди сюда!","Энд ир!"]],
 q:[["___ книгу! (ты, читать)",["Читай","Читайте","Читает"],0],["___, пожалуйста. (вы, писать)",["Пишите","Пиши","Пишет"],0],["___ говори так!",["Не","Нет","Ни"],0]],
