 q:[["Sie ist ___ Jahre alt. (21)",["einundzwanzig","zwanzigeins","einzwanzig"],0],["Das kostet ___ Euro. (50)",["fünfzig","fünfzehn","fünfzigen"],0],["Es ist ___ Uhr. (12)",["zwölf","zwei","zehn"],0]],
